  \begin{minipage}[t]{0.48\textwidth}
    \begin{algorithm}[H]
      \caption{\small Motion-adaptive Noise Propagation}
\label{algorithm}
\textbf{Notations:} Initialize noise $x$ with $N$ frames, $x^n \leftarrow \mathcal{N}(0, I) , n=0,...,(N-1) $ 
Input Video $: v = [ v^n, n=0,...,(N-1) ] $ 
$R_{thres}$ : Threshold for residual change 
\textbf{residual-based}
\For{ i from 1 to N}{
$ res = norm( v^i - v^{(i-1)} ) $ \\
$ res_{mask} = res > R_{thres} $ \\    
$res_{mask}$ = $DownSample(res_{mask})$ \\
$x^i = [x^i - x^{(i-1)} ]* res_{mask} +  x^{(i-1)}$ \\
}
\textbf{flow-based}
\For{ i from 1 to N}{
$ flow^i_{pixel} = flow( v^i , v^{(i-1)} ) $ \\
$ flow^i_{latent} $ = $DownSample(flow_{pixel})$ \\
$ x^i = GridSample(x^{(i-1)}, flow^i_{latent})$ \\ % gridsample?
}
    \end{algorithm}
