    \begin{algorithm}[H]
      \caption{\small Spatial-Temporal Reward Feedback Learning for Video Diffusion Models}
\label{algorithm_rlhf}
\textbf{Notations:} Video diffusion model $w$, quality reward model $R_q$, motion reward $R_m$. Total scheduler time steps $T$, randomly sampled timestep $t \in [T1, T2] $. Input latent $x$, output latent $x'$. $\alpha$ is the learning rate. \\
t $\gets$ rand(T1,T2) \\ 
$x_T$ $\sim$ $\mathcal{N}(0, I)$ \\
with no grad:  \\
\For{ i from T to t+2}{ 
$x_{i-1}$ $\gets$ $w(x_i)$ \\
}
with grad: $x_{t}$ $\gets$ $w(x_{t+1})$ \\
$x_0'$ $\gets$ $x_t$  \quad  // predict \\
$v_0'$ $\gets$ $x_0'$, $v_0$ $\gets$ $x_0$   \quad // decode   \\
$L_{motion}$ $\gets$ $R_{m}(v_0, v_0')$, $L_{quality} \gets R_{q}(v_0')$ \\
$\mathcal{L}_{ST} \gets L_{motion} + L_{quality}$ \\
$\Delta \gets \frac{\partial \mathcal{L}_{ST}}{\partial w}$ \\
$w'$ $\gets$ w - $\alpha$ $\Delta$  \quad // update 
    \end{algorithm}
